 readonly StackPanel cargoPalette=new(){Spacing=5,Width=180,HorizontalAlignment=HorizontalAlignment.Right,VerticalAlignment=VerticalAlignment.Top,Margin=new Thickness(12),Visibility=Visibility.Collapsed};
 string? cargoPaletteKey;
 CargoResource[] CargoChoices(){if(vehicleConfiguration==null)return [];if(VehicleBoxFrame)return vehicleCatalog?.Objects.Where(o=>o.Type=="VEHICLETYPE_ROAD").Select(o=>new CargoResource(Path.Combine(Path.GetDirectoryName(o.Script)!,"main.nmf"),o.Name)).Where(r=>File.Exists(r.File)&&File.Exists(Path.Combine(Path.GetDirectoryName(r.File)!,"material.mtl"))).ToArray()??[];var f=VehicleScript.Fields(vehicleConfiguration);string transport=f.FirstOrDefault(x=>x.Key=="RESOURCE_TRANSPORT_TYPE")?.Value??"";var allowed=f.Where(x=>x.Key=="RESOURCE_ALLOW_ONLY").Select(x=>x.Value).ToArray();string? media=MediaFolder();return media==null?[]:(allowed.Length==0?VehicleCatalog.CargoResources(transport,null,UiLanguage.English):allowed.SelectMany(r=>VehicleCatalog.CargoResources(transport,r,UiLanguage.English))).DistinctBy(r=>r.File).Where(r=>File.Exists(Path.Combine(media,"resources",r.File))&&MaterialDocuments.ResourceMaterial(Path.Combine(media,"resources",r.File))!=null).ToArray();}
 async Task LoadCargoResource(CargoResource resource){string path=Path.IsPathRooted(resource.File)?resource.File:Path.Combine(MediaFolder()!,"resources",resource.File);var model=await Task.Run(()=>new NativeModel(File.ReadAllBytes(path)));string material=VehicleBoxFrame?Path.Combine(Path.GetDirectoryName(path)!,"material.mtl"):MaterialDocuments.ResourceMaterial(path)??throw new FileNotFoundException("Cargo material missing");_=MaterialDocuments.ResourceMaps(model,material);cargoModel=model;cargoModelPath=path;cargoMtl=material;showCargo=true;}
 async Task ConfigureCargo(){await LoadVehicleChoices();vehicleConfiguration??=VehicleTemplate();var fields=VehicleScript.Fields(vehicleConfiguration);string transport=fields.FirstOrDefault(f=>f.Key=="RESOURCE_TRANSPORT_TYPE")?.Value??"";bool joint=fields.Any(f=>f.Key=="JOINT");var frames=new List<(string Key,string Name)>{("RESOURCE_VISUALIZATION","Кузов")};if(joint)frames.Add(("RESOURCE_VISUALIZATION_JOINT","Прицеп"));if(fields.Any(f=>f.Key=="RESOURCE_VISUALIZATION_BONE"))frames.Add(("RESOURCE_VISUALIZATION_BONE","Кость"));if(transport is "RESOURCE_TRANSPORT_OPEN" or "RESOURCE_TRANSPORT_GENERAL"||fields.Any(f=>f.Key=="CARGOVEHICLE_VISUALIZATION"))frames.Add(("CARGOVEHICLE_VISUALIZATION","Перевозимая техника"));if(joint&&(transport is "RESOURCE_TRANSPORT_OPEN" or "RESOURCE_TRANSPORT_GENERAL"))frames.Add(("CARGOVEHICLE_VISUALIZATION_JOINT","Техника на прицепе"));var choice=new ComboBox{ItemsSource=frames.Select(f=>UiLanguage.Text(f.Name)).ToArray(),SelectedIndex=Math.Max(0,frames.FindIndex(f=>f.Key==cargoFrame)),HorizontalAlignment=HorizontalAlignment.Stretch};if(frames.Count>1&&await ShowDialog(VehicleDialog("Размещение груза",choice))!=ContentDialogResult.Primary)return;cargoFrame=frames[choice.SelectedIndex].Key;cargoBone=fields.FirstOrDefault(f=>f.Key==cargoFrame)?.Value;if(cargoFrame.Contains("JOINT",StringComparison.Ordinal))_=JointModel();int count=fields.Count(f=>f.Key==cargoFrame);await OpenCargoSlot(activeCargo>=0&&activeCargo<count?activeCargo:0);}
 async Task OpenCargoSlot(int slot)
 {
  if(cargoFrame=="RESOURCE_VISUALIZATION_BONE")cargoBone=VehicleScript.Fields(vehicleConfiguration!).FirstOrDefault(f=>f.Key==cargoFrame&&f.Occurrence==slot)?.Value??cargoBone;var choices=CargoChoices();if(choices.Length==0)throw new InvalidDataException(UiLanguage.Text("Для этого класса нет видимого груза"));var selected=choices.FirstOrDefault(c=>c.File==cargoModelPath||c.File==Path.GetFileName(cargoModelPath))??choices.FirstOrDefault(c=>Path.GetFileName(Path.GetDirectoryName(c.File)!).StartsWith("personal_",StringComparison.OrdinalIgnoreCase))??choices[0];await LoadCargoResource(selected);var layout=VehicleBoxFrame?null:VehicleScript.Cargo(vehicleConfiguration!,slot,cargoFrame);
  if(VehicleBoxFrame){if(VehicleCargoBox.Read(vehicleConfiguration!,cargoFrame,slot)==null){var bounds=ModelOrientation.Bounds(cargoFrame.Contains("JOINT",StringComparison.Ordinal)?JointModel():lods.First().Value);vehicleConfiguration=VehicleCargoBox.Write(vehicleConfiguration!,cargoFrame,slot,new(new(bounds.Min.X,bounds.Max.Y,bounds.Min.Z),new(bounds.Max.X,bounds.Max.Y,bounds.Max.Z)));vehicleConfigurationEdited=true;}}else if(layout==null){var vehicle=ModelOrientation.Bounds(cargoFrame.Contains("JOINT",StringComparison.Ordinal)?JointModel():lods.First().Value);var cargo=ModelOrientation.Bounds(cargoModel!);var size=vehicle.Max-vehicle.Min;var cargoSize=cargo.Max-cargo.Min;var scale=new Vector3(Math.Max(.01f,size.X*.8f/Math.Max(.01f,cargoSize.X)),Math.Max(.01f,size.Y*.3f/Math.Max(.01f,cargoSize.Y)),Math.Max(.01f,size.Z*.4f/Math.Max(.01f,cargoSize.Z)));var p=new Vector3((vehicle.Min.X+vehicle.Max.X)/2,vehicle.Min.Y+size.Y*.5f,(vehicle.Min.Z+vehicle.Max.Z)/2);layout=new(Vector3.Zero,p,scale*.1f,p,scale);vehicleConfiguration=VehicleScript.SetCargo(vehicleConfiguration!,layout,slot,cargoFrame,cargoBone);vehicleConfigurationEdited=true;}
  transportPoint=null;activeCargo=slot;activeSmoke=-1;activeLamp=-1;cargoEndpoint=1;cargoFill=1;gizmoVisible=gizmoEditing=true;gizmoMode="move";dirty=true;await Display();SetStatus("Настройка груза");
 }
 void RefreshCargoPalette()
 {
  cargoPalette.Visibility=gizmoVisible&&activeCargo>=0?Visibility.Visible:Visibility.Collapsed;if(cargoPalette.Visibility!=Visibility.Visible)return;var choices=CargoChoices();int count=VehicleScript.Fields(vehicleConfiguration!).Count(f=>f.Key==cargoFrame);string key=cargoFrame+"|"+activeCargo+"|"+count+"|"+cargoModelPath+"|"+UiLanguage.English+"|"+string.Join(";",choices.Select(c=>c.File));if(cargoPaletteKey==key)return;cargoPaletteKey=key;cargoPalette.Children.Clear();
  var area=new ComboBox{ItemsSource=Enumerable.Range(0,count).Select(i=>UiLanguage.Text("Область")+" "+(i+1)).ToArray(),SelectedIndex=activeCargo,HorizontalAlignment=HorizontalAlignment.Stretch};area.SelectionChanged+=async(_,_)=>{if(!busy&&area.SelectedIndex>=0&&area.SelectedIndex!=activeCargo)await RunCommand(()=>OpenCargoSlot(area.SelectedIndex));};cargoPalette.Children.Add(area);
  var actions=new StackPanel{Orientation=Orientation.Horizontal,Spacing=5};var add=new Button{Content="+"};add.Click+=async(_,_)=>await RunCommand(()=>OpenCargoSlot(count));var remove=new Button{Content=UiLanguage.Text("Удалить")};remove.Click+=async(_,_)=>await RunCommand(async()=>{vehicleConfiguration=VehicleBoxFrame?VehicleCargoBox.Write(vehicleConfiguration!,cargoFrame,activeCargo,null):VehicleScript.SetCargo(vehicleConfiguration!,null,activeCargo,cargoFrame);vehicleConfigurationEdited=true;activeCargo=count>1?Math.Min(activeCargo,count-2):-1;if(activeCargo<0){showCargo=false;gizmoVisible=false;}dirty=true;await Display();});actions.Children.Add(add);actions.Children.Add(remove);cargoPalette.Children.Add(actions);
  var buttons=new StackPanel{Spacing=4};foreach(var choice in choices){var button=new Button{Content=choice.Name,HorizontalAlignment=HorizontalAlignment.Stretch,IsEnabled=choice.File!=cargoModelPath&&choice.File!=Path.GetFileName(cargoModelPath)};button.Click+=async(_,_)=>await RunCommand(async()=>{await LoadCargoResource(choice);dirty=true;await Display();});buttons.Children.Add(button);}cargoPalette.Children.Add(new ScrollViewer{Content=buttons,MaxHeight=250,VerticalScrollBarVisibility=ScrollBarVisibility.Auto});
 }
 object BuildViewportScene(NativeModel model)
 {
  var materials=model.Materials.ToList();var entries=new List<object>();
  if(!CabinFrameRequested)foreach(var n in MechanismPreviewNodes(model))entries.Add(new{n.Name,n.Positions,n.Normals,n.Uv,Indices=n.Indices.Select(i=>(int)i).ToArray(),n.Groups,Cargo=false});
  AppendAssemblyParts(materials,entries);
  if(showCargo&&cargoModel!=null&&vehicleConfiguration!=null&&cargoFrame.Contains("JOINT",StringComparison.Ordinal)==JointFrameRequested){
   int first=materials.Count;materials.AddRange(cargoModel.Materials.Select(m=>"__cargo__"+m));int count=VehicleScript.Fields(vehicleConfiguration).Count(f=>f.Key==cargoFrame);
   for(int slot=0;slot<count;slot++){
    var cargo=VehicleBoxFrame?VehicleCargoBox.Preview(VehicleCargoBox.Read(vehicleConfiguration,cargoFrame,slot)!,cargoModel):VehicleScript.Cargo(vehicleConfiguration,slot,cargoFrame)!;var scale=Vector3.Lerp(cargo.EmptyScale,cargo.FullScale,cargoFill);if(MathF.Min(scale.X,MathF.Min(scale.Y,scale.Z))<=1e-6f&&slot!=activeCargo)continue;
    var rotation=cargo.Rotation;var transform=Matrix4x4.CreateScale(scale)*Matrix4x4.CreateRotationX(rotation.X)*Matrix4x4.CreateRotationY(rotation.Y)*Matrix4x4.CreateRotationZ(rotation.Z)*Matrix4x4.CreateTranslation(Vector3.Lerp(cargo.EmptyPosition,cargo.FullPosition,cargoFill));if(!Matrix4x4.Invert(transform,out var inverse))inverse=Matrix4x4.Identity;var normalTransform=Matrix4x4.Transpose(inverse);
    foreach(var n in cargoModel.Nodes){var positions=new float[n.Positions.Length];var normals=new float[n.Normals.Length];for(int i=0;i<n.VertexCount;i++){var p=Vector3.Transform(new(n.Positions[i*3],n.Positions[i*3+1],n.Positions[i*3+2]),transform);var normal=Vector3.Normalize(Vector3.TransformNormal(new(n.Normals[i*3],n.Normals[i*3+1],n.Normals[i*3+2]),normalTransform));positions[i*3]=p.X;positions[i*3+1]=p.Y;positions[i*3+2]=p.Z;normals[i*3]=normal.X;normals[i*3+1]=normal.Y;normals[i*3+2]=normal.Z;}entries.Add(new{Name="Cargo_"+slot+"_"+n.Name,Positions=positions,Normals=normals,n.Uv,Indices=n.Indices.Select(i=>(int)i).ToArray(),Groups=n.Groups.Select(g=>g with{Material=g.Material+first}).ToArray(),Cargo=true,CargoSlot=slot,LocalPositions=n.Positions,LocalNormals=n.Normals});}
   }
  }return new{Materials=materials,Nodes=entries};
 }
 async Task LoadCargoTextures(){if(!showCargo||cargoMtl==null)return;foreach(var p in MaterialDocuments.ResourceMaps(cargoModel!,cargoMtl))await ApplyPreview("__cargo__"+p.Key,p.Value);}
